import{z as n,x as o,o as r,c as d,q as B,j as s,D as e,d as t,s as A,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"VAR 尺度自回归","description":"","frontmatter":{"title":"VAR 尺度自回归","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/var-next-scale.md","filePath":"llm/var-next-scale.md","lastUpdated":1791063341000}'),p={name:"llm/var-next-scale.md"};function m(c,a,_,h,D,u){const l=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="var-尺度自回归" tabindex="-1">VAR 尺度自回归 <a class="header-anchor" href="#var-尺度自回归" aria-label="Permalink to &quot;VAR 尺度自回归&quot;">​</a></h1><div class="epigraph"><p>下一格是局部的。下一尺度是整张图从粗到细。把自回归定义在分辨率金字塔上，布局先于纹理。</p><footer>—— Tian 等 Visual Autoregressive Modeling（next-scale prediction）</footer></div><p><a href="/llm/autoregressive-image-gen">上一课</a>在 raster 码上逐步写格。缺口是分解顺序：人看图是先轮廓后细节，不是先左上角一个 patch。VAR 把 \\(p\\) 定义在多尺度 token 图上：先预测最低分辨率整图，再条件于它预测更高一层。后课 MAR 默认：仍可自回归，但不必须离散码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>raster AR 的因果掩码与二维邻域冲突，长程竖直依赖要绕一整行。多尺度向量量化（或残差尺度）给出 \\(r_1,r_2,\\ldots\\)：每层是该分辨率的完整离散图。Next-scale 预测整层，层内可并行（训练用双向或块掩码，推理按尺度步进）。这把「先布局后纹理」写进似然分解，而不是指望深层注意力自己学出来。</p><p><span class="marginnote">术语翻译：「多尺度 token 图」就是给同一张图准备几份不同分辨率的离散马赛克——粗的一份几个大格就拼出轮廓，细的一份把每个大格再切碎补细节。next-scale 预测就是先猜粗马赛克，再一层层猜细的。</span></p><p>与理解侧原生分辨率不同：这里的多尺度是生成课程，不是阅读任意 \\(H\\times W\\)。</p><p><span class="marginnote">层内并行使训练吞吐高于纯 raster，但尺度数目、每层码本与上采样器都是新超参。尺度对不齐会棋盘或结构错位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造尺度金字塔 tokenizer，按粗→细训练自回归（或块自回归）目标。采样必须从最粗层开始，不能随机从中层插入。验收看全局结构（对称、物体完整）是否优于同预算 raster，而不只是 FID 小数。</p>',10)),(r(),s(i,null,{default:e(()=>[A(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E7%B2%97%E5%B0%BA%E5%BA%A6%E6%95%B4%E5%9B%BE%22%5D%20--%3E%20S2%5B%22%E4%B8%8B%E4%B8%80%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E6%9B%B4%E7%BB%86%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20S3%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%83%8F%E7%B4%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"条件链是 \\(p(r_{k}\\mid r_{\\lt k})\\)。粗层错误会变成细层的错误布局，但粗层很短，布局被提前钉死，细层只补纹理。这与扩散从纯噪声同时出布局和纹理不同，也与 raster 把布局拖到序列中段不同。",-1)),(r(),s(i,null,{default:e(()=>[A(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22raster%20AR%EF%BC%9A%E6%8C%89%E8%A1%8C%E9%80%90%E6%A0%BC%E5%86%99%22%5D%20--%3E%20RA%5B%22%E9%95%BF%E7%A8%8B%E4%BE%9D%E8%B5%96%E8%A6%81%E7%BB%95%E6%95%B4%E8%A1%8C%22%5D%0A%20%20RA%20--%3E%20RB%5B%22%E5%B8%83%E5%B1%80%E5%88%B0%E5%BA%8F%E5%88%97%E4%B8%AD%E6%AE%B5%E6%89%8D%E6%88%90%E5%BD%A2%22%5D%0A%20%20V%5B%22VAR%EF%BC%9A%E5%85%88%E9%A2%84%E6%B5%8B%E6%9C%80%E7%B2%97%E5%B1%82%E6%95%B4%E5%9B%BE%22%5D%20--%3E%20VA%5B%22%E7%9F%AD%E5%BA%8F%E5%88%97%E6%8F%90%E5%89%8D%E9%92%89%E6%AD%BB%E5%B8%83%E5%B1%80%22%5D%0A%20%20VA%20--%3E%20VB%5B%22%E7%BB%86%E5%B1%82%E6%9D%A1%E4%BB%B6%E4%BA%8E%E5%B8%83%E5%B1%80%E8%A1%A5%E7%BA%B9%E7%90%86%22%5D%0A%20%20RB%20--%3E%20CMP%5B%22%E5%90%8C%E4%B8%80%E8%87%AA%E5%9B%9E%E5%BD%92%E6%A1%86%E6%9E%B6%EF%BC%8C%E4%B8%A4%E7%A7%8D%E5%88%86%E8%A7%A3%E9%A1%BA%E5%BA%8F%22%5D%0A%20%20VB%20--%3E%20CMP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">直觉类比：像画壁画先起铅笔稿再上色。铅笔稿（粗层）错了，颜色涂得再好整体也是错的；但稿子只有几笔，出错概率与返工成本都小。raster 则像从左上角一格一格涂颜色，画到中盘才知道整张图像什么。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VAR 仍吃离散量化损失。下一课用掩码自回归在连续表示上生成，避开码本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VAR 用 next-scale 代替 next-token raster。</li><li>布局在短粗序列上先决定，纹理后补。</li><li>仍受离散 tokenizer 天花板约束。</li><li>出处：Tian 等 VAR。</li></ul>',5))])}const x=n(p,[["render",m]]);export{V as __pageData,x as default};
